/**
 * Bridge for CaptureModal (Svelte content, no captureModalBody innerHTML).
 */

import { awaitLazyModalReady } from '../lib/lazyModalMounts.ts';

export type CaptureBallOption = {
  type: string;
  count: number;
  name: string;
  img: string;
  icon: string;
  visualRate: number;
  barColor: string;
  disabled: boolean;
};

export type CaptureModalData = {
  title: string;
  enemyName: string;
  enemyRarity: string;
  enemyLevel: number;
  spriteUrl: string;
  skipLabel: string;
  balls: CaptureBallOption[];
  sceneStyles?: Record<string, string>;
};

type ShowFn = (data: CaptureModalData) => void;
type CloseFn = () => void;

let _show: ShowFn | null = null;
let _close: CloseFn | null = null;
let _pendingShow: CaptureModalData | null = null;

export function setCaptureModalShow(fn: ShowFn): void {
  _show = fn;
  if (_pendingShow) {
    fn(_pendingShow);
    _pendingShow = null;
  }
}
export function setCaptureModalClose(fn: CloseFn): void { _close = fn; }

export async function showCaptureModal(data: CaptureModalData): Promise<void> {
  await awaitLazyModalReady('captureModal');
  if (_show) _show(data);
  else _pendingShow = data;
}

export function closeCaptureModal(): void {
  _close?.();
  document.getElementById('captureModal')?.classList.remove('show');
}

if (typeof globalThis !== 'undefined') {
  (globalThis as Record<string, unknown>).__showCaptureModal = showCaptureModal;
  (globalThis as Record<string, unknown>).__closeCaptureModal = closeCaptureModal;
}
